import{z as B,x as n,o as l,c as m,q as s,j as o,D as e,d as E,s as i,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"请求调度的基础与指标","description":"","frontmatter":{"title":"请求调度的基础与指标","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-basics-metrics.md","filePath":"llm/sch-basics-metrics.md","lastUpdated":1791413859000}'),T={name:"llm/sch-basics-metrics.md"};function d(h,a,p,D,C,c){const r=n("Mermaid");return l(),m("div",null,[a[2]||(a[2]=s('<h1 id="请求调度的基础与指标" tabindex="-1">请求调度的基础与指标 <a class="header-anchor" href="#请求调度的基础与指标" aria-label="Permalink to &quot;请求调度的基础与指标&quot;">​</a></h1><div class="epigraph"><p>调度器手里的硬通货只有两种：一次前向里的 token 名额，与 KV 池里的字节；指标不是报表，是给这两种通货的分配记账的账本。</p><footer>—— 据 Kwon et al., SOSP 2023 的调度器口径与 Little, Operations Research, 1961 整理</footer></div><p><a href="/llm/kv-map">上一课</a>把 KV 管理与压缩的十三课压成一张决策单，结尾留了话头：缓存管好之后，瓶颈移向「谁在什么时候用池子」。本课是「服务调度与多租户」的第一课，钉三件事：调度器到底控制什么、用什么指标记账、为什么指标合同必须先于任何机制。迭代级调度的来历与调度器循环主干已有专文（<a href="/llm/iteration-scheduling">iteration-level 调度</a>、<a href="/llm/vllm-scheduler">vLLM 调度器</a>），本课不重推，只立全课程共用的骨架。后课默认你已经会用 TTFT、TPOT、goodput 三本账去审任何调度决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调度器是推理服务热路径上唯一做分配的组件。每个迭代它决定三件事：本轮哪些请求参与前向、每个请求本步最多写多少 token、谁的 KV 留在池子里。它控制的是两种耦合的资源：<strong>算力名额</strong>决定本步走多久，<strong>KV 字节</strong>决定谁还能继续 decode。麻烦在到达过程完全未知：提示长度、输出长度、到达间隔都是随机变量，而输出长度只有生成完才知道。</p><p>没有指标合同，任何调度改动都无法判定好坏：把批从 32 加到 64，利用率与吞吐都涨，TTFT 尾部也涨——这是变好还是变坏，答案不在引擎里，在合同里。缺口因此不是某个算法，而是先把「什么算好」钉死，再谈怎么调度；本课程后面的每一课都在这套账本上评审。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给每条请求记三个时刻：\\(t_{\\mathrm{arrive}}\\)、\\(t_{\\mathrm{first}}\\)、\\(t_{\\mathrm{last}}\\)。于是 \\(\\mathrm{TTFT}=t_{\\mathrm{first}}-t_{\\mathrm{arrive}}\\)，\\(\\mathrm{TPOT}=(t_{\\mathrm{last}}-t_{\\mathrm{first}})/(n-1)\\)，\\(\\mathrm{E2E}=t_{\\mathrm{last}}-t_{\\mathrm{arrive}}\\)。<span class="marginnote">术语翻译：TTFT 就是「从发出请求到吐出第一个字等了多久」，TPOT 是「之后每个字平均隔多久再蹦出来一个」。聊天产品里 TTFT 决定界面像不像卡死了，TPOT 决定逐字输出读起来顺不顺——两者是不同的账，混在一个平均值里就都看不清了。</span>三笔账要在服务端、按请求级、按类别分别记：交互聊天与离线摘要写进同一列平均值里，两张脸都看不清。吞吐是单位时间完成的 token 数；<strong>goodput</strong> 是满足双 SLO 的请求速率——它才是调度要最大化的量，定义见<a href="/llm/goodput">有效吞吐 Goodput</a>。</p><p>排队侧用 Little 定律 \\(L=\\lambda W\\)：每秒到达 4 条、平均停留 25 s，系统里平均同时在线 100 条。<span class="marginnote">数字实例：把 4 条/秒换成促销开抢的 40 条/秒、停留时间不变，在线并发就从 100 涨到 1000。Little 定律的用处是反向的：先承诺「P99 延迟不超过多少」，据此算出 W 和必须容纳的 L，再决定池子和卡数——而不是先买机器再看能扛多少。</span>这条算式给出容量规划的第一行：承诺的延迟决定了必须容纳的并发，而不是反过来。调度器据此维护三个集合——等待、运行、被换出——各自的进出条件是后课全部机制的地基，循环本身见 <a href="/llm/vllm-scheduler">vLLM 调度器</a>。</p>',9)),(l(),o(A,null,{default:e(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E5%88%B0%E8%BE%BE%EF%BC%9A%E6%8F%90%E7%A4%BA%E4%B8%8E%E5%8F%82%E6%95%B0%22%5D%20--%3E%20TOK%5B%22tokenize%20%E4%B8%8E%E8%AE%A1%E9%87%8F%22%5D%0A%20%20TOK%20--%3E%20ADM%7B%22%E5%87%86%E5%85%A5%EF%BC%9A%E9%85%8D%E9%A2%9D%E4%B8%8E%E6%B0%B4%E4%BD%8D%22%7D%0A%20%20ADM%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20REJ%5B%22429%20%E6%88%96%E9%99%8D%E7%BA%A7%22%5D%0A%20%20ADM%20--%3E%7C%E8%BF%9B%E5%85%A5%7C%20WQ%5B%22%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20WQ%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E6%9C%AC%E8%BD%AE%E6%88%90%E5%91%98%E4%B8%8E%20token%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20SCH%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%22%5D%0A%20%20ENG%20--%3E%20LED%5B%22%E9%80%90%E8%AF%B7%E6%B1%82%E8%AE%B0%E8%B4%A6%EF%BC%9ATTFT%20%E4%B8%8E%20TPOT%22%5D%0A%20%20LED%20--%3E%20SLO%7B%22%E8%BE%BE%E6%A0%87%22%7D%0A%20%20SLO%20--%3E%7C%E6%98%AF%7C%20G%5B%22%E8%AE%A1%E5%85%A5%20goodput%22%5D%0A%20%20SLO%20--%3E%7C%E5%90%A6%7C%20B%5B%22%E8%AE%A1%E5%85%A5%E8%BF%9D%E7%BA%A6%EF%BC%9A%E6%8C%89%E7%B1%BB%E5%88%86%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("指标先于机制，是因为调度是个最优化问题，指标就是目标函数；换目标函数，同一个机制的评价会反转。FCFS 对吞吐友好、对 TTFT 尾部不友好；抢占保住新请求的 TTFT，代价是老请求的 TPOT 出现空洞——哪边对，取决于合同写的是哪个分位数。"),t("span",{class:"marginnote"},"常见误区：初学者容易把 P99 读成「平均水平的 99%」，其实它是把所有请求按延迟从快到慢排序后，第 99 百分位上那个请求的延迟——100 个请求里倒数第二慢的那个。均值漂亮而 P99 爆炸，说明多数人没事、一小撮倒霉蛋在坐牢，合同盯住的正是这一撮。"),E("自回归服务的停留时间方差极大，尾巴由 \\(\\max\\) 而不是均值决定，所以合同必须写成「P99 TTFT \\(\\lt\\) 800 ms、P99 TPOT \\(\\lt\\) 60 ms」这样的分位数对，而不是一个平均延迟。利用率尤其不能当目标：它度量「忙」，不度量「忙得对不对」。把 prefill 塞满每一步，利用率很好看，交互流的 ITL 已经烂掉，见 "),t("a",{href:"/llm/serving-slo"},"服务 SLO 与尾延迟"),E("。调度器维护的三个集合，可以看成请求在系统里的三种状态：")],-1)),(l(),o(A,null,{default:e(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20NEW%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E5%BE%85%E9%9B%86%22%5D%0A%20%20WAIT%20--%3E%7C%22%E5%85%A5%E9%80%89%E6%9C%AC%E8%BD%AE%E5%89%8D%E5%90%91%22%7C%20RUN%5B%22%E8%BF%90%E8%A1%8C%E9%9B%86%22%5D%0A%20%20RUN%20--%3E%7C%22%E7%94%9F%E6%88%90%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%20token%22%7C%20DONE%5B%22%E5%AE%8C%E6%88%90%EF%BC%8C%E6%8C%89%E7%B1%BB%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20RUN%20--%3E%7C%22KV%20%E6%B1%A0%E6%BB%A1%E6%88%96%E8%A2%AB%E6%8A%A2%E5%8D%A0%22%7C%20SWAP%5B%22%E8%A2%AB%E6%8D%A2%E5%87%BA%E9%9B%86%22%5D%0A%20%20SWAP%20--%3E%7C%22KV%20%E5%86%99%E5%9B%9E%E6%B1%A0%E5%AD%90%E5%90%8E%E6%81%A2%E5%A4%8D%22%7C%20RUN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">排队论的老结论在 LLM 服务上原样成立：M/M/1 在利用率 \\(\\rho=0.9\\) 时，平均逗留时间已是空载的 10 倍，\\(\\rho\\to 1\\) 时爆炸。这就是容量规划永远要留头部余量的原因，也是「再加点负载试试」的实验必须在离峰期做的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指标合同不解决公平与隔离：先到先得、按权重分、按承诺分是三种不同的正义，后课分别处理。调度也不能凭空造容量：并发当旋钮扫出的是延迟-吞吐前沿，两端不可同时最优，见 <a href="/llm/latency-throughput-pareto">延迟-吞吐帕累托</a>。测量本身有坑：客户端测的 E2E 含网络与客户端排队，与服务端账不同源；重试不去重会把同一请求记三次，分位数被改写。本课程的默认模型是服务端、请求级、分分类别记账；所有后续机制在这套账本上评审。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调度器控制两种耦合资源：每步的算力名额与 KV 池字节；到达与输出长度是未知量。</li><li>指标合同先于机制：TTFT、TPOT、E2E 按请求分列，goodput 是要最大化的量。</li><li>Little 定律 \\(L=\\lambda W\\) 给出并发期望，是容量规划的第一行。</li><li>合同写成双分位数；均值与利用率都不能签字。</li><li>利用率是体检指标不是目标；只报吞吐会选出填满批的坏配置。</li><li>出处：调度器口径见 Kwon et al., SOSP 2023 与 Yu et al., OSDI 2022；Little 定律出自 Little, Operations Research, 1961。</li></ul>',5))])}const f=B(T,[["render",d]]);export{_ as __pageData,f as default};
